int futex_wait_requeue_pi(u32 __user *uaddr, unsigned int flags, u32 val,
                          ktime_t *abs_time, u32 bitset, u32 __user *uaddr2)
{
    int ret = 0;
    struct hrtimer shtimer;
    struct hrtimer_sleeper hs;
    struct futex_hash_bucket *bucket;
    struct futex_pi_state *pi_state = NULL;
    struct futex_q q = { }, q_requeue = { };
    u32 uval;

    if (get_user(uval, uaddr))
        return -EFAULT;

    if (uval != val)
        return -EWOULDBLOCK;

    q.pi_state = NULL;
    q.requeue_pi = 1;
    q.bitset = bitset;
    q.key = *futex_get_key(uaddr, flags);

    bucket = futex_hash_get(&q.key);
    spin_lock(&bucket->lock);

    ret = futex_wait_setup(uaddr, val, flags, &q, &pi_state);
    if (ret)
        goto out_unlock;

    if (abs_time) {
        hrtimer_init_sleeper(&hs, &shtimer);
        hrtimer_set_expires(&shtimer, ktime_to_timespec(*abs_time));
        hrtimer_start_expires(&shtimer, HRTIMER_MODE_ABS);
        set_current_state(TASK_INTERRUPTIBLE);
    }

    ret = futex_wait_woken(&q, flags, &shtimer, &hs);
    if (ret)
        goto out_unlock;

    if (abs_time) {
        if (hrtimer_active(&shtimer))
            ret = -ETIMEDOUT;
        else
            ret = 0;
    }

    futex_requeue_pi(&q, uaddr2);
out_unlock:
    spin_unlock(&bucket->lock);
    futex_put_key(&q.key);
    if (pi_state)
        futex_pi_state_free(pi_state);
    return ret;
}
